from .api_base import API_base 

class Reverse_Geocode_API(API_base):
    """
    This API performs reverse geocoding by converting a latitude and longitude pair into a human-readable address or location.
    """
    def __init__(self):
        pass

    def execute(self, **params):
        expected_params = set(["p_lat", "p_lon"])
        unexpected_params = set(params.keys()) - expected_params 
        if unexpected_params:
            return self.handle_error(f"Unexpected parameters: {', '.join(unexpected_params)}", 400)
        p_lat = params.get('p_lat', None)
        if p_lat is None:
            return self.handle_error(f"Required parameter 'p_lat' is missing", 400)
        is_valid, error = self.validate_type(p_lat, 'p_lat', str)
        if not is_valid:
            return error
        
        p_lon = params.get('p_lon', None)
        if p_lon is None:
            return self.handle_error(f"Required parameter 'p_lon' is missing", 400)
        is_valid, error = self.validate_type(p_lon, 'p_lon', str)
        if not is_valid:
            return error
        
        return {
            "status_code": 200, 
            "results": {
                "function_name": "Reverse_Geocode_API",
                "p_lat": p_lat,
                "p_lon": p_lon
            }
        }

