class Distance_Calculator(API_base):
    """
    This API calculates the geodesic and great circle distances between two points on the Earth's surface, given their latitude and longitude coordinates.
    """
    def __init__(self):
        pass

    def execute(self, **params):
        expected_params = set(["p_start_latitude", "p_start_longitude", "p_end_latitude", "p_end_longitude"])
