class ThunderstormPredictor_predictStorm(API_base):
    """
    Predicts the probability of a thunderstorm based on the current weather conditions and historical data.
    """
    def __init__(self):
        pass

    def execute(self, **params):
        expected_params = set(["p_currentConditions", "p_historicalData"])
        unexpected_params = set(params.keys()) - expected_params 
        if unexpected_params:
            return self.handle_error(f"Unexpected parameters: {', '.join(unexpected_params)}", 400)
        p_currentConditions = params.get('p_currentConditions', None)
