class HydrationMonitor_calculateWaterIntake(API_base):
    """
    Calculates the optimal amount of water intake based on the user's weight, activity level and climate.
    """
    def __init__(self):
        pass

    def execute(self, **params):
        expected_params = set(["p_weight", "p_activityLevel", "p_climate"])
        unexpected_params = set(params.keys()) - expected_params 
        if unexpected_params:
            return self.handle_error(f"Unexpected parameters: {', '.join(unexpected_params)}", 400)
        p_weight = params.get('p_weight', None)
        if p_weight is None:
            return self.handle_error(f"Required parameter 'p_weight' is missing", 400)
        is_valid, error = self.validate_type(p_weight, 'p_weight', (float, int))
        if not is_valid:
            return error
        if p_weight is not None:
            p_weight = float(p_weight)
        
        p_activityLevel = params.get('p_activityLevel', None)
        if p_activityLevel is None:
            return self.handle_error(f"Required parameter 'p_activityLevel' is missing", 400)
        is_valid, error = self.validate_type(p_activityLevel, 'p_activityLevel', str)
        if not is_valid:
            return error
        
        if p_activityLevel is not None and p_activityLevel not in ["low", "medium", "high"]:
            return self.handle_error(f"Parameter 'p_activityLevel' not in valid enum", 400)
        
        p_climate = params.get('p_climate', None)
        if p_climate is None:
            return self.handle_error(f"Required parameter 'p_climate' is missing", 400)
        is_valid, error = self.validate_type(p_climate, 'p_climate', str)
        if not is_valid:
            return error
        
        if p_climate is not None and p_climate not in ["cold", "temperate", "hot"]:
            return self.handle_error(f"Parameter 'p_climate' not in valid enum", 400)
        
        return {
            "status_code": 200, 
            "results": {
                "function_name": "HydrationMonitor_calculateWaterIntake",
                "p_weight": p_weight,
                "p_activityLevel": p_activityLevel,
                "p_climate": p_climate
            }
        }

